/*
  Reference data: Ports, the eight sailings and their day-by-day itineraries.
  GENERATED by `npm run db:seed:gen` from the TypeScript fixtures in src/. Do not edit by hand: change the source and regenerate.
  Idempotent: each table is a MERGE on its key, so re-running updates rows in place and adds missing ones. It never deletes.
  Run after db/01-schema.sql:  sqlcmd -S <server> -d <db> -b -i <this file>   (plain ASCII, no code page needed)
*/
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
GO

-- ref.Ports: 5 rows
MERGE ref.Ports AS t
USING (VALUES
  (N'sea', N'At sea', N'', N'America/New_York', 0, N'', N'[]'),
  (N'fll', N'Fort Lauderdale (Port Everglades)', N'United States', N'America/New_York', 0, N'', N'[]'),
  (N'cozumel', N'Cozumel, Mexico', N'Mexico', N'America/Cancun', 0, N'A passport is the safest document. Closed-loop cruise passengers who are US citizens may use a birth certificate and photo ID. Verify before travel.', N'{"consulate":"U.S. consular agency, Cozumel: 555-0141","emergency":"911 (Mexico)","agent":"Ship' + NCHAR(8217) + N's agent, Cozumel pier: 555-0142"}'),
  (N'belize', N'Belize City, Belize', N'Belize', N'America/Belize', 1, N'Cruise passengers go ashore by tender. A passport is recommended. Verify before travel.', N'{"consulate":"U.S. Embassy, Belmopan: 555-0151","emergency":"911 (Belize)","agent":"Ship' + NCHAR(8217) + N's agent, Belize tender pier: 555-0152"}'),
  (N'roatan', N'Roat' + NCHAR(225) + N'n, Honduras', N'Honduras', N'America/Tegucigalpa', 0, N'A passport is recommended. Some visitors pay a small port or tourism fee. Verify before travel.', N'{"consulate":"U.S. Embassy, Tegucigalpa: 555-0161","emergency":"911 (Honduras)","agent":"Ship' + NCHAR(8217) + N's agent, Mahogany Bay: 555-0162"}')
) AS s ([Id], [Name], [Country], [TimeZone], [Tender], [EntryNote], [Contacts])
ON t.[Id] = s.[Id]
WHEN MATCHED THEN UPDATE SET t.[Name] = s.[Name], t.[Country] = s.[Country], t.[TimeZone] = s.[TimeZone], t.[Tender] = s.[Tender], t.[EntryNote] = s.[EntryNote], t.[Contacts] = s.[Contacts]
WHEN NOT MATCHED THEN INSERT ([Id], [Name], [Country], [TimeZone], [Tender], [EntryNote], [Contacts]) VALUES (s.[Id], s.[Name], s.[Country], s.[TimeZone], s.[Tender], s.[EntryNote], s.[Contacts]);
GO

-- ref.Sailings: 8 rows
MERGE ref.Sailings AS t
USING (VALUES
  (N'sun-2026-11-08', N'sun-princess', CAST('2026-11-08' AS DATE), 7, 0, 0, N'Western Caribbean, 7 nights from Fort Lauderdale, 2026-11-08', 1),
  (N'sun-2026-11-22', N'sun-princess', CAST('2026-11-22' AS DATE), 7, 0, 0, N'Western Caribbean, 7 nights from Fort Lauderdale, 2026-11-22', 1),
  (N'sun-2026-12-06', N'sun-princess', CAST('2026-12-06' AS DATE), 7, 0, 0, N'Western Caribbean, 7 nights from Fort Lauderdale, 2026-12-06', 1),
  (N'sun-2026-12-27', N'sun-princess', CAST('2026-12-27' AS DATE), 7, 1, 0, N'Holiday Western Caribbean, 7 nights from Fort Lauderdale, 2026-12-27', 1),
  (N'sun-2027-01-17', N'sun-princess', CAST('2027-01-17' AS DATE), 7, 0, 0, N'Western Caribbean, 7 nights from Fort Lauderdale, 2027-01-17', 1),
  (N'sun-2027-02-07', N'sun-princess', CAST('2027-02-07' AS DATE), 7, 0, 0, N'Western Caribbean, 7 nights from Fort Lauderdale, 2027-02-07', 1),
  (N'sun-2027-02-28', N'sun-princess', CAST('2027-02-28' AS DATE), 7, 0, 0, N'Western Caribbean, 7 nights from Fort Lauderdale, 2027-02-28', 1),
  (N'sun-2027-03-21', N'sun-princess', CAST('2027-03-21' AS DATE), 7, 0, 1, N'Western Caribbean, 7 nights from Fort Lauderdale, 2027-03-21', 1)
) AS s ([Id], [ShipId], [Departure], [Nights], [IsHoliday], [IsReference], [Title], [BookingOpen])
ON t.[Id] = s.[Id]
WHEN MATCHED THEN UPDATE SET t.[ShipId] = s.[ShipId], t.[Departure] = s.[Departure], t.[Nights] = s.[Nights], t.[IsHoliday] = s.[IsHoliday], t.[IsReference] = s.[IsReference], t.[Title] = s.[Title], t.[BookingOpen] = s.[BookingOpen]
WHEN NOT MATCHED THEN INSERT ([Id], [ShipId], [Departure], [Nights], [IsHoliday], [IsReference], [Title], [BookingOpen]) VALUES (s.[Id], s.[ShipId], s.[Departure], s.[Nights], s.[IsHoliday], s.[IsReference], s.[Title], s.[BookingOpen]);
GO

